370	/** „Schöne“ Achsenschritte für einen Wertebereich */
371	function achse(lo, hi, ziel = 6) {
372	  const roh = Math.max((hi - lo) / ziel, 1e-9);
373	  const p = 10 ** Math.floor(Math.log10(roh));
374	  const schritt = [1, 2, 2.5, 5, 10].map((k) => k * p).find((k) => k >= roh) || 10 * p;
375	  const a = Math.floor(lo / schritt) * schritt;
376	  const b = Math.ceil(hi / schritt) * schritt;
377	  const ticks = [];
378	  for (let v = a; v <= b + schritt / 2; v += schritt) ticks.push(Number(v.toFixed(6)));
379	  return { lo: a, hi: b, ticks };
380	}
