382	function useGeometrie(breite, n, yMin, yMax) {
383	  const H = breite < 520 ? 280 : 340;
384	  const m = { l: breite < 520 ? 44 : 52, r: 12, t: 26, b: 30 };
385	  const pw = Math.max(10, breite - m.l - m.r);
386	  const ph = H - m.t - m.b;
387	  const band = pw / Math.max(1, n);
388	  return { H, m, pw, ph, band, x: (i) => m.l + band * (i + 0.5), y: (v) => m.t + (1 - (v - yMin) / (yMax - yMin || 1)) * ph };
389	}
