391	function Flaeche({ g, n, aktiv, setAktiv, label, breite, children }) {
392	  const ausPos = (clientX, el) => {
393	    const r = el.getBoundingClientRect();
394	    setAktiv(Math.max(0, Math.min(n - 1, Math.floor((clientX - r.left - g.m.l) / g.band))));
395	  };
396	  return (
397	    <svg
398	      width="100%"
399	      height={g.H}
400	      viewBox={`0 0 ${breite} ${g.H}`}
401	      className="block touch-pan-y select-none rounded-xl outline-none focus-visible:ring-2 focus-visible:ring-ov-500 focus-visible:ring-offset-2"
402	      role="img"
403	      aria-label={label}
404	      tabIndex={0}
405	      onPointerMove={(e) => ausPos(e.clientX, e.currentTarget)}
406	      onPointerDown={(e) => ausPos(e.clientX, e.currentTarget)}
407	      onPointerLeave={() => setAktiv(null)}
408	      onBlur={() => setAktiv(null)}
409	      onKeyDown={(e) => {
410	        if (e.key === "ArrowRight" || e.key === "ArrowLeft") {
411	          e.preventDefault();
412	          const d = e.key === "ArrowRight" ? 1 : -1;
413	          setAktiv((a) => (a == null ? (d > 0 ? 0 : n - 1) : Math.max(0, Math.min(n - 1, a + d))));
414	        }
415	        if (e.key === "Escape") setAktiv(null);
416	      }}
417	    >
418	      {children}
419	    </svg>
420	  );
421	}
