427	      <text x={g.m.l - 8} y={g.y(v)} dy="0.32em" textAnchor="end" fontSize="11.5" fill={FARBE.achse} className="ov-num">
428	        {format(v)}
429	      </text>
430	    </g>
431	  ));
432	}
