434	function JahresMarken({ daten, g, breite }) {
435	  const starts = daten.map((a, i) => ({ i, jahr: a.datum.slice(0, 4) })).filter((d, k, arr) => k === 0 || arr[k - 1].jahr !== d.jahr);
436	  const jedes = breite < 520 && starts.length > 5 ? 2 : 1;
437	  return starts.map((d, k) =>
438	    k % jedes === 0 ? (
439	      <text key={d.jahr} x={g.m.l + g.band * d.i} y={g.H - 10} fontSize="11.5" fill={FARBE.achse} className="ov-num">
440	        {d.jahr}
441	      </text>
442	    ) : null
443	  );
444	}
