446	/** Pfad aus Punkten; Lücken (null) unterbrechen die Linie */
447	function pfadAus(punkte) {
448	  let d = "";
449	  let neu = true;
450	  for (const p of punkte) {
451	    if (!p) {
452	      neu = true;
453	      continue;
454	    }
455	    d += `${neu ? "M" : "L"}${p[0].toFixed(1)},${p[1].toFixed(1)}`;
456	    neu = false;
457	  }
458	  return d;
459	}
