537	function MengenDiagramm({ serie: s, name }) {
538	  const { t, f, datum, mw } = useTeile();
539	  const [ref, breite] = useBreite(760);
540	  const [aktiv, setAktiv] = useState(null);
541	  const daten = s.runden;
542	  const n = daten.length;
543	  const { hi, ticks } = achse(0, Math.max(...daten.map((d) => Math.max(d.volumen || 0, d.zuschlag || 0, d.gebote || 0))), 5);
544	  const g = useGeometrie(breite, n, 0, hi);
545	  const bw = Math.max(2, Math.min(18, (g.band - 6) / 2));
546	  const a = aktiv != null ? daten[aktiv] : null;
547	  const balken = (x, v, farbe, key, i) => {
548	    if (v == null) return null;
549	    const y0 = g.y(0);
550	    const y1 = g.y(v);
551	    const h = Math.max(0, y0 - y1);
552	    const r = Math.min(3, h, bw / 2);
553	    return <path key={key} d={`M${x},${y0}V${y1 + r}Q${x},${y1} ${x + r},${y1}H${x + bw - r}Q${x + bw},${y1} ${x + bw},${y1 + r}V${y0}Z`} fill={farbe} className="ov-balken-y" style={{ "--i": i }} />;
554	  };
555	  return (
556	    <figure>
557	      <Legende
558	        eintraege={[
559	          { art: "balken", farbe: FARBE.volumen, label: t.legVolumen },
560	          { art: "balken", farbe: FARBE.zuschlag, label: t.legZuschlag },
