566	          <text x={2} y={10} fontSize="10.5" fill={FARBE.achse}>
567	            MW
568	          </text>
569	          <JahresMarken daten={daten} g={g} breite={breite} />
570	          {a && <rect x={g.m.l + g.band * aktiv + 1} y={g.m.t} width={Math.max(0, g.band - 2)} height={g.ph} rx="6" fill="#151a24" fillOpacity="0.04" />}
571	          {daten.map((d, i) => (
572	            <g key={d.datum}>
573	              {balken(g.x(i) - bw - 0.5, d.volumen, FARBE.volumen, "v", i / 2)}
574	              {balken(g.x(i) + 0.5, d.zuschlag, FARBE.zuschlag, "z", i / 2 + 0.25)}
575	            </g>
576	          ))}
577	        </Flaeche>
578	        {a && (
579	          <Tooltip x={g.x(aktiv)} y={g.y(Math.max(a.volumen || 0, a.zuschlag || 0)) - 10} breite={breite}>
580	            <p className="font-semibold">{datum(a.datum)}</p>
581	            <p>
582	              {t.legVolumen}: <strong className="ov-num">{mw(a.volumen)} MW</strong>
583	            </p>
584	            {a.gebote != null && (
585	              <p>
586	                {t.kopf[2]}: <strong className="ov-num">{mw(a.gebote)}</strong>
587	              </p>
588	            )}
589	            <p>
590	              {t.legZuschlag}: <strong className="ov-num">{mw(a.zuschlag)} MW</strong>
591	            </p>
592	          </Tooltip>
593	        )}
594	      </div>
595	      <figcaption className="mt-3 text-[12.5px] leading-relaxed text-ink-500">{t.fussMengen(s.stelle)}</figcaption>
596	    </figure>
597	  );
598	}
